import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getPublicVendor, getVendorCatalogCards } from "../../../lib/catalog-view";
import { SiteHeader } from "../../../components/SiteHeader";
import { CatalogProductCard } from "../../../components/CatalogProductCard";
type Props = Readonly<{ params: Promise<{ id: string }> }>;
export async function generateMetadata({ params }: Props): Promise<Metadata> { const { id } = await params; const vendor = await getPublicVendor(id); return { title: vendor ? `${vendor.name} · Τοπικό κατάστημα` : "Κατάστημα" }; }
export default async function VendorPage({ params }: Props) { const { id } = await params; const vendor = await getPublicVendor(id); if (!vendor) notFound(); const products = await getVendorCatalogCards(id); return <main><div className="announcement">Know your vendor · γνώρισε τον άνθρωπο πίσω από την αγορά.</div><SiteHeader /><section className="vendor-profile-hero"><div className="shell vendor-profile-grid"><div><div className="eyebrow light">Verified local partner · Demo profile</div><h1>{vendor.name}</h1><p>Το Buy Local Sparta δίνει χώρο στην ιστορία και στην τεχνογνωσία του καταστήματος, όχι μόνο στα προϊόντα του.</p><div className="vendor-profile-actions"><a className="button button-light" href="/#advice">Ρώτησε {vendor.adviser ?? "το κατάστημα"}</a><a className="button vendor-outline" href="/shop">Δες την αγορά</a></div></div><div className="merchant-portrait"><span>{(vendor.adviser ?? vendor.name).slice(0,1)}</span><small>{vendor.adviser ?? "Local adviser"}<br/>Local adviser</small></div></div></section><section className="shell section"><div className="section-heading"><div><div className="eyebrow">Η επιλογή του συνεργάτη</div><h2>Προϊόντα που εξυπηρετούνται εδώ τώρα</h2></div><p className="section-note">Η σελίδα δείχνει canonical προϊόντα που το κατάστημα μπορεί να εξυπηρετήσει, χωρίς να δημιουργεί Fair Vendor Exposure γεγονότα ή να αποκαλύπτει κρυφές τιμές προμηθευτή.</p></div>{products.length ? <div className="product-grid">{products.map((product, index) => <CatalogProductCard product={product} index={index} vendorContext={{ name: vendor.name, adviser: vendor.adviser }} key={product.id} />)}</div> : <div className="empty-state"><h2>Δεν υπάρχουν διαθέσιμα canonical προϊόντα για αυτό το προφίλ.</h2><p>Δεν υπάρχουν αυτή τη στιγμή canonical products συνδεδεμένα με ενεργή προσφορά αυτού του demo καταστήματος.</p><a className="button" href="/shop">Δες όλα τα προϊόντα</a></div>}</section></main>; }
